CREATE OR REPLACE FUNCTION public.guard_commercial_limits() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; limits jsonb; allowed integer; existing integer; BEGIN IF TG_TABLE_NAME='businesses' THEN bid:=NEW.id; IF TG_OP='UPDATE' AND cardinality(NEW.photos)<=cardinality(OLD.photos) THEN RETURN NEW; END IF; ELSE bid:=NEW.business_id; END IF; IF public.has_permission('commerce.manage',bid) THEN RETURN NEW; END IF; limits:=public.effective_business_plan(bid)->'entitlements'; IF TG_TABLE_NAME='businesses' THEN allowed:=coalesce((limits->>'max_photos')::integer,10); IF cardinality(NEW.photos)>allowed THEN RAISE EXCEPTION 'Current plan photo limit reached'; END IF; ELSE allowed:=coalesce((limits->>'max_offerings')::integer,100); SELECT count(*) INTO existing FROM public.business_offerings WHERE business_id=bid; IF existing>=allowed THEN RAISE EXCEPTION 'Current plan catalogue limit reached'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER enforce_business_photo_entitlement BEFORE INSERT OR UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_limits();
CREATE TRIGGER enforce_offering_entitlement BEFORE INSERT ON public.business_offerings FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_limits();
CREATE OR REPLACE FUNCTION public.public_content() RETURNS TABLE(key text,kind text,payload jsonb,updated_at timestamptz) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT key,kind,published,published_at FROM public.site_content WHERE published IS NOT NULL AND kind<>'redirect'; $$;
CREATE OR REPLACE FUNCTION public.effective_business_plan(bid uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=bid AND (b.status='approved' AND b.archived_at IS NULL OR b.owner_id=auth.uid() OR public.has_permission('commerce.manage',bid))) THEN coalesce((SELECT jsonb_build_object('key',p.key,'entitlements',p.entitlements,'ends_at',s.ends_at) FROM public.business_subscriptions s JOIN public.plan_definitions p ON p.id=s.plan_id WHERE s.business_id=bid AND s.status='active' AND s.starts_at<=now() AND s.ends_at>now() AND p.active ORDER BY s.ends_at DESC LIMIT 1),'{"key":"free","entitlements":{}}'::jsonb) ELSE '{"key":"free","entitlements":{}}'::jsonb END; $$;
CREATE OR REPLACE FUNCTION public.guard_content_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p jsonb; BEGIN FOREACH p IN ARRAY ARRAY[NEW.draft,NEW.published] LOOP IF p IS NULL THEN CONTINUE; END IF; IF length(p->>'title')>180 OR length(p->>'body')>20000 OR length(p->>'source')>1000 OR coalesce(p->>'href','') ~ '[\\\x00-\x1f]' THEN RAISE EXCEPTION 'Invalid content fields'; END IF; IF coalesce(p->>'image','')<>'' AND p->>'image' !~ '^https://' THEN RAISE EXCEPTION 'Content image must use HTTPS'; END IF; END LOOP; RETURN NEW; END; $$;
CREATE TRIGGER validate_content_fields BEFORE INSERT OR UPDATE ON public.site_content FOR EACH ROW EXECUTE FUNCTION public.guard_content_fields();